export interface Product {
  id: string;
  name: string;
  stock: number;
}

export interface CatalogueProduct {
  id: string;
  name: string;
  stock: number;
}

export function createProduct(id: string, name: string, stock: number): Product {
  if (!id.trim()) throw new DomainError("Product id is required");
  if (!name.trim()) throw new DomainError("Product name is required");
  if (!Number.isSafeInteger(stock) || stock < 0) {
    throw new DomainError("Stock must be a non-negative integer");
  }
  return { id, name, stock };
}

export class DomainError extends Error {
  public constructor(message: string) {
    super(message);
    this.name = "DomainError";
  }
}

